if(!exists('fit_fractional_lgd'))library(creditratingsystem)
lgdm_near<-function(x,y,tol=1e-7)stopifnot(isTRUE(all.equal(as.numeric(unlist(x)),as.numeric(y),tolerance=tol,check.attributes=FALSE)))
lgdm_error<-function(code,expr){e<-tryCatch({force(expr);NULL},error=identity);stopifnot(inherits(e,'creditratingsystem_error'),identical(e$code,code))}
lgdm_target<-list(event='economic_loss',horizon=5,time_unit='years',probability_measure='PHYSICAL',conditioning='given_default')
lgdm_training<-list(data_fingerprint='hand-designed',split_id='train',known_at='2025-12-31',data_origin='SYNTHETIC',workout_population='closed_defaulted_episodes')
lgdm_fit<-function(y,X=matrix(numeric(),length(y),0),feature_order=character(),...)fit_fractional_lgd(X,y,feature_order,'logit','HC0',lgdm_target,lgdm_training,'lgd','1',...)
y<-c(0,.2,.8,1);f<-lgdm_fit(y);lgdm_near(f$model$parameters$coefficients,0);lgdm_near(f$model$parameters$covariance,sum((y-.5)^2))
lgdm_near(lgdm_fit(rep(.5,3))$model$parameters$covariance,0);lgdm_error('SEPARATION',lgdm_fit(rep(1,3)))
x<-matrix(c(0,0,1,1),4,1);y<-c(0,.5,.5,1);f<-lgdm_fit(y,x,'group',weights=rep(2,4));lgdm_near(f$model$parameters$coefficients,c(-log(3),2*log(3)))
ff<-lgdm_fit(rep(y,each=2),x[rep(1:4,each=2),,drop=FALSE],'group');lgdm_near(f$model$parameters$covariance,unlist(ff$model$parameters$covariance),1e-12)
lgdm_beta<-function(y,...)fit_beta_lgd(matrix(numeric(),length(y),0),y,character(),'logit','log',lgdm_target,lgdm_training,'lgd','1',...)
lgdm_phi<-function(y)uniroot(function(p)digamma(p)-digamma(p/2)+mean(log(y)),c(.01,1000),tol=1e-12)$root
y<-c(.1,.2,.8,.9);f<-lgdm_beta(y);lgdm_near(f$model$parameters$mean_coefficients,0);lgdm_near(exp(unlist(f$model$parameters$precision_coefficients)),lgdm_phi(y))
y<-c(y,.4,.45,.55,.6);f<-lgdm_beta(y,precision_design=matrix(rep(0:1,each=4),8,1),precision_feature_order='group');p<-log(c(lgdm_phi(y[1:4]),lgdm_phi(y[5:8])));lgdm_near(f$model$parameters$precision_coefficients,c(p[1],p[2]-p[1]),1e-6)
lgdm_error('INVALID_LGD_TARGET',lgdm_beta(c(0,.2,.8,1)));lgdm_error('NON_IDENTIFIABLE',lgdm_beta(rep(.5,4)))
cat('Native LGD model independent oracles PASS\n')
y<-c(.1,.2,.8,.9);f<-lgdm_beta(y);v<-predict_lgd(f,matrix(numeric(),1,0),character(),lgdm_target,'given_default',quantile_levels=c(.1,.5,.9))$value;phi<-lgdm_phi(y);lgdm_near(v$quantiles,qbeta(c(.1,.5,.9),phi/2,phi/2))
lgdm_error('DISTRIBUTION_NOT_IDENTIFIED',predict_lgd(lgdm_fit(y),matrix(numeric(),1,0),character(),lgdm_target,'given_default',quantile_levels=.5))
y<-c(0,0,1,1,.1,.2,.8,.9);f<-fit_zero_one_inflated_lgd(matrix(numeric(),8,0),y,character(),list(boundary_origin='structural',gate_link='logit'),lgdm_target,lgdm_training,'lgd','1');v<-predict_lgd(f,matrix(numeric(),1,0),character(),lgdm_target,'given_default',quantile_levels=c(.1,.25,.5,.75,.9))$value
lgdm_near(v$zero_probability,.25);lgdm_near(v$one_probability,.25);lgdm_near(v$mean_lgd,.5);lgdm_near(v$quantiles,c(0,0,.5,1,1))
bad_target<-lgdm_target;bad_target$conditioning<-'performing';lgdm_error('INCOMPATIBLE_TARGET',fit_fractional_lgd(matrix(numeric(),4,0),c(0,.2,.8,1),character(),'logit','HC0',bad_target,lgdm_training,'x','1'))
lgdm_error('INSUFFICIENT_COMPONENT_SUPPORT',fit_zero_one_inflated_lgd(matrix(numeric(),4,0),c(0,.2,.8,.9),character(),list(boundary_origin='structural',gate_link='logit'),lgdm_target,lgdm_training,'x','1'))
f<-lgdm_beta(c(.1,.2,.8,.9));bad_target<-lgdm_target;bad_target$horizon<-1;lgdm_error('TARGET_MISMATCH',predict_lgd(f,matrix(numeric(),1,0),character(),bad_target,'given_default'))
f$model$parameters$precision_coefficients<-list(0,1);lgdm_error('INVALID_MODEL',predict_lgd(f,matrix(numeric(),1,0),character(),lgdm_target,'given_default'))
f<-lgdm_fit(c(0,.2,.8,1));for(ctx in list(list(probability_measure='RISK_NEUTRAL'),list(horizon=1),list(conditioning='performing'),list(model_version='2')))lgdm_error('TARGET_MISMATCH',predict_lgd(f,matrix(numeric(),1,0),character(),lgdm_target,'given_default',context=ctx))
p<-predict_lgd(f,matrix(numeric(),1,0),character(),lgdm_target,'given_default');stopifnot(p$provenance$data_origin=='SYNTHETIC',p$provenance$parameter_origin=='ESTIMATED')
